import{_ as n,C as s,o as t,c as i,a2 as a,b as d,w as r,a as l,E as c,a3 as h}from"./chunks/framework.XaTYfhfj.js";const _=JSON.parse('{"title":"14.13 Real-Time Systems, WebSockets & Event Streaming","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.13-real-time-systems.md","filePath":"system-design/14.13-real-time-systems.md"}'),m={name:"system-design/14.13-real-time-systems.md"};function u(p,e,b,g,y,S){const o=s("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="_14-13-real-time-systems-websockets-event-streaming" tabindex="-1">14.13 Real-Time Systems, WebSockets &amp; Event Streaming <a class="header-anchor" href="#_14-13-real-time-systems-websockets-event-streaming" aria-label="Permalink to &quot;14.13 Real-Time Systems, WebSockets &amp; Event Streaming&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Real-time systems provide immediate, bidirectional or push-based data synchronization between servers and browsers without requiring the user to refresh the page or poll repeatedly.</p><hr><h2 id="_2-real-time-telemetry-topology-in-truthguard" tabindex="-1">2. Real-Time Telemetry Topology in TruthGuard <a class="header-anchor" href="#_2-real-time-telemetry-topology-in-truthguard" aria-label="Permalink to &quot;2. Real-Time Telemetry Topology in TruthGuard&quot;">​</a></h2>',5)),(t(),d(h,null,{default:r(()=>[c(o,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Analyst1%5BAnalyst%20A%5D%20--%3E%7CWebSocket%20Connection%7C%20EdgeGateway%5BSupabase%20Realtime%20%2F%20WebSocket%20Server%5D%0A%20%20%20%20Analyst2%5BAnalyst%20B%5D%20--%3E%7CWebSocket%20Connection%7C%20EdgeGateway%0A%20%20%20%20%0A%20%20%20%20EdgeGateway%20%3C--%3E%20RedisCluster%5BRedis%20Pub%2FSub%20Backplane%5D%0A%20%20%20%20%0A%20%20%20%20EdgeGateway%20--%3E%20PostgresWAL%5BPostgreSQL%20Write-Ahead%20Log%3A%20Logical%20Replication%5D%0A%20%20%20%20PostgresWAL%20-.-%3E%7CBroadcast%20Event%7C%20EdgeGateway%0A%20%20%20%20EdgeGateway%20--%3E%7CPush%20Live%20Threat%20Alert%7C%20Analyst1%0A%20%20%20%20EdgeGateway%20--%3E%7CPush%20Live%20Threat%20Alert%7C%20Analyst2%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_3-real-time-transport-protocols-compared" tabindex="-1">3. Real-Time Transport Protocols Compared <a class="header-anchor" href="#_3-real-time-transport-protocols-compared" aria-label="Permalink to &quot;3. Real-Time Transport Protocols Compared&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Protocol</th><th>Directionality</th><th>Protocol</th><th>Reconnection Handling</th><th>Overhead</th><th>Fit with TruthGuard</th></tr></thead><tbody><tr><td><strong>Server-Sent Events (SSE)</strong></td><td>Unidirectional (Server -&gt; Client)</td><td>HTTP/2</td><td>Built-in browser retry</td><td>Very Low</td><td><strong>Optimal for Live Threat Feeds</strong></td></tr><tr><td><strong>WebSockets</strong></td><td>Full-Duplex (Bidirectional)</td><td>TCP Upgrade</td><td>Requires custom heartbeat</td><td>Low</td><td>Best for Collaborative Canvas</td></tr><tr><td><strong>Short Polling</strong></td><td>Unidirectional (Client -&gt; Server)</td><td>HTTP/1.1</td><td>N/A</td><td>High (Repeated headers)</td><td>Outdated</td></tr><tr><td><strong>Long Polling</strong></td><td>Emulated Push</td><td>HTTP/1.1</td><td>Handled on connection close</td><td>Moderate</td><td>Fallback only</td></tr></tbody></table><hr><h2 id="_4-connection-scaling-the-pub-sub-backplane" tabindex="-1">4. Connection Scaling &amp; The Pub/Sub Backplane <a class="header-anchor" href="#_4-connection-scaling-the-pub-sub-backplane" aria-label="Permalink to &quot;4. Connection Scaling &amp; The Pub/Sub Backplane&quot;">​</a></h2><p>When thousands of analysts connect to real-time incident rooms across multiple load-balanced server nodes:</p><ol><li><strong>The Problem</strong>: Analyst A connected to Server 1 cannot receive an alert emitted by Analyst B connected to Server 2 without a shared messaging bus.</li><li><strong>The Solution (Redis Pub/Sub)</strong>: Server nodes subscribe to a shared Redis cluster (<code>PUBLISH incident:alerts &lt;payload&gt;</code>). When any edge node processes a new threat, Redis broadcasts it instantly across all connected nodes to reach the target analysts.</li></ol><hr><h2 id="_5-30-second-spoken-interview-answer" tabindex="-1">5. 30-Second Spoken Interview Answer <a class="header-anchor" href="#_5-30-second-spoken-interview-answer" aria-label="Permalink to &quot;5. 30-Second Spoken Interview Answer&quot;">​</a></h2><blockquote><p>&quot;For real-time incident telemetry, we recommend Server-Sent Events over HTTP/2 for unidirectional alert streams because SSE natively reconnects through firewalls without the connection upgrade overhead of WebSockets.</p><p>To scale concurrent connections across multiple backend instances, we use Redis Pub/Sub as our horizontal backplane, ensuring that an alert broadcast on one server node reaches analysts connected to any other node in under 5 milliseconds.&quot;</p></blockquote>',10))])}const P=n(m,[["render",u]]);export{_ as __pageData,P as default};
